// the keys at each level in the order the template writes them; the bubbles and glow live under transcript
const TOP = ["clawd", "transcript", "minimap", "teacher"] as const;
const UNDER = [
  "prompt",
  "reply",
  "bash",
  "read",
  "edit",
  "write",
  "agent",
  "skill",
  "peer",
  "glow",
