import { cells, wrapRuns } from "./text";

export type Kind =
  | "prompt"
  | "cmd"
  | "flag"
  | "str"
  | "var"
  | "op"
  | "comment"
  | "text"
  | "space";
type Token = { text: string; kind: Kind };

// longest first, so `&&` is never read as two `&`
const OPS = ["2>&1", "&&", "||", ">>", "$(", "|", ";", "(", ")", ">", "<", "&"];
// after these the next word is a file or an argument, not a command
const TAKES_ARG = new Set([")", ">", "<", ">>", "2>&1"]);

// a highlighter's reading, not a parser's: heredocs and nested quoting fall back to plain words
export const tokenize = (line: string): Token[] => {
  const out: Token[] = [];
  let expectCmd = true;
  let i = 0;
  while (i < line.length) {
    const rest = line.slice(i);
    const take = (text: string, kind: Kind) => {
      out.push({ text, kind });
      i += text.length;
    };
    const space = rest.match(/^\s+/)?.[0];
    if (space) {
      take(space, "space");
      continue;
    }
    if (rest[0] === "#") {
      take(rest, "comment");
      break;
    }
    const op = OPS.find((o) => rest.startsWith(o));
    if (op) {
      take(op, "op");
      expectCmd = !TAKES_ARG.has(op);
      continue;
    }
    const quoted =
      rest.match(/^"(?:\\.|[^"\\])*"?/)?.[0] ?? rest.match(/^'[^']*'?/)?.[0];
    if (quoted) {
      take(quoted, "str");
      expectCmd = false;
      continue;
    }
    const variable = rest.match(/^\$(?:\{[^}]*\}|\w+|[?@#$!*])/)?.[0];
    if (variable) {
      take(variable, "var");
      expectCmd = false;
      continue;
    }
    const word = rest.match(/^[^\s'"|&;()<>$]+/)?.[0] ?? rest.charAt(0);
    if (expectCmd && /^\w+=/.test(word)) take(word, "var");
    else if (expectCmd) {
      take(word, "cmd");
      expectCmd = false;
    } else take(word, /^-/.test(word) ? "flag" : "text");
  }
  return out;
};

const CONTINUE: Token = { text: "  ", kind: "prompt" };

// a line too wide for the row breaks before each top-level &&, || and |, then hard-wraps what is still too wide
export const layout = (command: string, width: number): Token[][] =>
  command.split("\n").flatMap((src, n) => {
    const lead = n === 0 ? "$ " : "  ";
    const fits = cells(lead + src) <= width;
    const segments: Token[][] = [[]];
    let depth = 0;
    for (const t of tokenize(src)) {
      if (t.kind === "op" && (t.text === "(" || t.text === "$(")) depth++;
      if (t.kind === "op" && t.text === ")") depth--;
      const current = segments[segments.length - 1]!;
      if (
        !fits &&
        depth === 0 &&
        t.kind === "op" &&
        ["&&", "||", "|"].includes(t.text) &&
        current.length
      )
        segments.push([t]);
      else current.push(t);
    }
    return segments.flatMap((seg, s) => {
      while (seg[0]?.kind === "space") seg.shift();
      while (seg[seg.length - 1]?.kind === "space") seg.pop();
      const head = {
        text: s === 0 ? lead : CONTINUE.text,
        kind: "prompt" as const,
      };
      return wrapRuns([head, ...seg], width, CONTINUE);
    });
  });

files.hooks/transcript/sniff.ts:
import { tokenize } from "./shell";

// chroma's lexer names, which glow reads off a fence
const BY_EXT: Record<string, string> = {
  ts: "typescript",
  tsx: "tsx",
  js: "javascript",
  mjs: "javascript",
  cjs: "javascript",
  jsx: "jsx",
  json: "json",
  rb: "ruby",
  py: "python",
  rs: "rust",
  go: "go",
  sh: "bash",
  bash: "bash",
  zsh: "bash",
  yaml: "yaml",
  yml: "yaml",
  toml: "toml",
  css: "css",
  html: "html",
  vue: "vue",
  sql: "sql",
  swift: "swift",
  lua: "lua",
  md: "markdown",
};

export const languageOf = (path: string): string | undefined =>
  BY_EXT[path.split(".").pop()!.toLowerCase()];

const READERS = new Set(["cat", "head", "tail", "bat", "sed"]);

// glow only helps output whose language is known: raw text through it turns `#` lines into headings and `-` lines into bullets
export const language = (
  command: string,
  stdout: string,
): string | undefined => {
  const out = stdout.trim();
  if (/^[[{]/.test(out)) {
    try {
      JSON.parse(out);
      return "json";
    } catch {}
  }
  if (/^(diff --git |--- a\/|@@ )/.test(out)) return "diff";

  const tokens = tokenize(command.trim()).filter((t) => t.kind !== "space");
  if (tokens.some((t) => t.kind === "op")) return undefined;
  const [head, ...rest] = tokens;
  if (head?.kind !== "cmd" || !READERS.has(head.text)) return undefined;
  if (head.text === "sed" && !rest.some((t) => t.text === "-n"))
    return undefined;
  // a count like `head -n 5` is a bare word too, so a file is a word with an extension
  const files = rest.filter((t) => t.kind === "text" && /\.\w+$/.test(t.text));
  if (files.length !== 1) return undefined;
  return languageOf(files[0]!.text);
};

